175	/// The names a body uses as a component tag (`<Item/>`): a function or class the body declares under one of them is a
176	/// component of its own.
177	#[derive(Default)]
178	struct TagNames<'a> {
179	    names: FxHashSet<&'a str>,
180	}
181	
182	impl<'a> Visit<'a> for TagNames<'a> {
183	    fn visit_jsx_element_name(&mut self, it: &JSXElementName<'a>) {
184	        if let JSXElementName::IdentifierReference(id) = it {
185	            self.names.insert(id.name.as_str());
186	        }
187	    }
188	}
