190	/// What a name in scope is bound to.
191	#[derive(Debug, Clone, PartialEq, Eq)]
192	enum Bound {
193	    /// The props object: the first parameter.
194	    Props,
195	    /// The props object less some keys: a rest binding destructured from it.
196	    Rest,
197	    /// The value of one prop: a name destructured from the props object under this key.
198	    Prop(String),
199	    /// Anything else: a binding that shadows an outer one of the same name.
200	    Other,
201	}
202	
203	#[derive(Default)]
204	struct BodyReader<'a> {
205	    facts: BodyFacts,
206	    /// The scopes from the component function's inward, each with the names it binds.
207	    scopes: Vec<FxHashMap<&'a str, Bound>>,
208	    /// The functions and classes the body declares and renders as a tag: components of their own.
209	    nested_components: FxHashSet<&'a str>,
210	    /// How many nested components enclose the current node.
211	    nested: u32,
212	    /// The elements of the nested components.
213	    nested_usages: Vec<JsxUsage>,
214	}
