216	/// The names a binding pattern binds.
217	fn bound_names<'a>(pattern: &BindingPattern<'a>, out: &mut Vec<&'a str>) {
218	    match pattern {
219	        BindingPattern::BindingIdentifier(id) => out.push(id.name.as_str()),
220	        BindingPattern::AssignmentPattern(assignment) => bound_names(&assignment.left, out),
221	        BindingPattern::ObjectPattern(object) => {
222	            for property in &object.properties {
223	                bound_names(&property.value, out);
224	            }
225	            if let Some(rest) = &object.rest {
226	                bound_names(&rest.argument, out);
227	            }
228	        }
229	        BindingPattern::ArrayPattern(array) => {
230	            for element in array.elements.iter().flatten() {
231	                bound_names(element, out);
232	            }
233	            if let Some(rest) = &array.rest {
234	                bound_names(&rest.argument, out);
235	            }
236	        }
237	    }
238	}
