240	impl<'a> BodyReader<'a> {
241	    /// Binds `name` in the innermost scope; the component function's scope is always open while its body is read.
242	    fn bind(&mut self, name: &'a str, bound: Bound) {
243	        if self.scopes.is_empty() {
244	            self.scopes.push(FxHashMap::default());
245	        }
246	        if let Some(scope) = self.scopes.last_mut() {
247	            scope.insert(name, bound);
248	        }
249	    }
250	
251	    fn shadow(&mut self, pattern: &BindingPattern<'a>) {
252	        let mut names = Vec::new();
253	        bound_names(pattern, &mut names);
254	        for name in names {
255	            self.bind(name, Bound::Other);
256	        }
257	    }
258	
259	    /// Opens a function's scope with its parameters. The component's own first parameter is the props object.
260	    fn enter_params(&mut self, params: &FormalParameters<'a>, component: bool) {
261	        self.scopes.push(FxHashMap::default());
262	        for (index, param) in params.items.iter().enumerate() {
263	            if component && index == 0 {
264	                self.bind_props_param(&param.pattern);
265	            } else {
266	                self.shadow(&param.pattern);
267	            }
268	        }
269	        if let Some(rest) = &params.rest {
270	            self.shadow(&rest.rest.argument);
271	        }
272	    }
273	
274	    fn bind_props_param(&mut self, pattern: &BindingPattern<'a>) {
275	        match pattern {
276	            BindingPattern::BindingIdentifier(id) => self.bind(id.name.as_str(), Bound::Props),
277	            // `function C({ a } = {})`.
278	            BindingPattern::AssignmentPattern(assignment) => self.bind_props_param(&assignment.left),
279	            BindingPattern::ObjectPattern(object) => self.destructure(object),
280	            // An array pattern reads indices of the props object, which says nothing about its keys.
281	            BindingPattern::ArrayPattern(_) => {
282	                self.facts.handed_on = true;
283	                self.shadow(pattern);
284	            }
285	        }
286	    }
287	
288	    /// An object pattern destructured from the props object: each key is read, a name bound to a key is that prop's
289	    /// value, and a rest binding is the props object again. Default values are walked by the caller's visit.
290	    fn destructure(&mut self, object: &ObjectPattern<'a>) {
291	        for property in &object.properties {
292	            let Some(key) = property.key.static_name().map(|key| js_text::property_name(&key)) else {
293	                // `{ [k]: v }` reads a key the syntax does not name.
294	                self.facts.handed_on = true;
295	                self.shadow(&property.value);
296	                continue;
297	            };
298	            let local = match &property.value {
299	                BindingPattern::AssignmentPattern(assignment) => &assignment.left,
300	                value => value,
301	            };
302	            match local {
303	                BindingPattern::BindingIdentifier(id) => self.bind(id.name.as_str(), Bound::Prop(key.clone())),
304	                nested => self.shadow(nested),
305	            }
306	            self.read(key);
307	        }
308	        if let Some(rest) = &object.rest {
309	            match &rest.argument {
310	                BindingPattern::BindingIdentifier(id) => {
311	                    self.bind(id.name.as_str(), Bound::Rest);
312	                    if self.facts.rest.is_none() {
313	                        self.facts.rest = Some(id.name.to_string());
314	                    }
315	                }
316	                other => self.shadow(other),
317	            }
318	        }
319	    }
320	
321	    /// Binds, as shadows, what the statements of a scope declare: `let`, `const`, `using`, `class` and `function`.
322	    /// A `var` belongs to the function and can redeclare a parameter, so it is not taken to shadow.
323	    fn declare_statements(&mut self, statements: &[Statement<'a>]) {
324	        for statement in statements {
325	            match statement {
326	                Statement::VariableDeclaration(declaration) if declaration.kind != VariableDeclarationKind::Var => {
327	                    for declarator in &declaration.declarations {
328	                        self.shadow(&declarator.id);
329	                    }
330	                }
331	                Statement::FunctionDeclaration(function) => {
332	                    if let Some(id) = &function.id {
333	                        self.bind(id.name.as_str(), Bound::Other);
334	                    }
335	                }
336	                Statement::ClassDeclaration(class) => {
337	                    if let Some(id) = &class.id {
338	                        self.bind(id.name.as_str(), Bound::Other);
339	                    }
340	                }
341	                _ => {}
342	            }
343	        }
344	    }
345	
346	    fn scoped(&mut self, statements: &[Statement<'a>], walk: impl FnOnce(&mut Self)) {
347	        self.scopes.push(FxHashMap::default());
348	        self.declare_statements(statements);
349	        walk(self);
350	        self.scopes.pop();
351	    }
352	
353	    fn lookup(&self, name: &str) -> Option<&Bound> {
354	        self.scopes.iter().rev().find_map(|scope| scope.get(name))
355	    }
356	
357	    /// What the props object an identifier is: `Props` or `Rest`, or `None` for anything else.
358	    fn whole(&self, name: &str) -> Option<SpreadOf> {
359	        match self.lookup(name) {
360	            Some(Bound::Props) => Some(SpreadOf::Props),
361	            Some(Bound::Rest) => Some(SpreadOf::Rest),
362	            _ => None,
363	        }
364	    }
365	
366	    fn whole_expr(&self, expr: &Expression<'_>) -> Option<SpreadOf> {
367	        match expr {
368	            Expression::Identifier(id) => self.whole(id.name.as_str()),
369	            _ => None,
370	        }
371	    }
372	
373	    fn read(&mut self, prop: String) {
374	        if !self.facts.reads.contains(&prop) {
375	            self.facts.reads.push(prop);
376	        }
377	    }
378	
379	    /// The prop a member read names, when its object is the props object: `props.x`, `props?.['x']`, `rest.x`.
380	    fn member_prop(&self, expr: &Expression<'_>) -> Option<String> {
381	        match expr {
382	            Expression::StaticMemberExpression(member) if self.whole_expr(&member.object).is_some() => {
383	                Some(member.property.name.to_string())
384	            }
385	            Expression::ComputedMemberExpression(member) if self.whole_expr(&member.object).is_some() => {
386	                match &member.expression {
387	                    Expression::StringLiteral(key) => Some(js_text::lossy(key.value).into_owned()),
388	                    _ => None,
389	                }
390	            }
391	            Expression::ChainExpression(chain) => match &chain.expression {
392	                ChainElement::StaticMemberExpression(member) if self.whole_expr(&member.object).is_some() => {
393	                    Some(member.property.name.to_string())
394	                }
395	                ChainElement::ComputedMemberExpression(member) if self.whole_expr(&member.object).is_some() => {
396	                    match &member.expression {
397	                        Expression::StringLiteral(key) => Some(js_text::lossy(key.value).into_owned()),
398	                        _ => None,
399	                    }
400	                }
401	                _ => None,
402	            },
403	            _ => None,
404	        }
405	    }
406	
407	    /// The prop an attribute's value is, when it is exactly one: a destructured name, `props.x` or `rest.x`.
408	    fn value_prop(&self, value: Option<&JSXAttributeValue<'_>>) -> Option<String> {
409	        let Some(JSXAttributeValue::ExpressionContainer(container)) = value else { return None };
410	        let expr = container.expression.as_expression()?;
411	        match expr {
412	            Expression::Identifier(id) => match self.lookup(id.name.as_str()) {
413	                Some(Bound::Prop(key)) => Some(key.clone()),
414	                _ => None,
415	            },
416	            _ => self.member_prop(expr),
417	        }
418	    }
