420	    fn in_nested(&mut self, nested: bool, walk: impl FnOnce(&mut Self)) {
421	        self.nested += u32::from(nested);
422	        walk(self);
423	        self.nested -= u32::from(nested);
424	    }
425	
426	    fn is_nested_component(&self, id: Option<&BindingIdentifier<'_>>) -> bool {
427	        id.is_some_and(|id| self.nested_components.contains(id.name.as_str()))
428	    }
429	}
