431	/// A tag as the JSX rule reads it: a lowercase first letter, a dash or a namespace makes it intrinsic.
432	fn tag_of(name: &JSXElementName<'_>) -> JsxTag {
433	    let identifier = |name: &str| {
434	        if name.starts_with(|c: char| c.is_ascii_lowercase()) || name.contains('-') {
435	            JsxTag::Intrinsic(name.to_owned())
436	        } else {
437	            JsxTag::Identifier(name.to_owned())
438	        }
439	    };
440	    match name {
441	        JSXElementName::Identifier(id) => identifier(id.name.as_str()),
442	        JSXElementName::IdentifierReference(id) => identifier(id.name.as_str()),
443	        JSXElementName::NamespacedName(namespaced) => {
444	            JsxTag::Intrinsic(format!("{}:{}", namespaced.namespace.name, namespaced.name.name))
445	        }
446	        JSXElementName::MemberExpression(member) => JsxTag::Member(member_path(member)),
447	        JSXElementName::ThisExpression(_) => JsxTag::Identifier("this".to_owned()),
448	    }
449	}
450	
451	fn member_path(member: &JSXMemberExpression<'_>) -> String {
452	    let object = match &member.object {
453	        JSXMemberExpressionObject::IdentifierReference(id) => id.name.to_string(),
454	        JSXMemberExpressionObject::MemberExpression(inner) => member_path(inner),
455	        JSXMemberExpressionObject::ThisExpression(_) => "this".to_owned(),
456	    };
457	    format!("{object}.{}", member.property.name)
458	}
459	
460	fn attribute_name(name: &JSXAttributeName<'_>) -> String {
461	    match name {
462	        JSXAttributeName::Identifier(id) => id.name.to_string(),
463	        JSXAttributeName::NamespacedName(namespaced) => {
464	            format!("{}:{}", namespaced.namespace.name, namespaced.name.name)
465	        }
466	    }
467	}
