469	impl<'a> Visit<'a> for BodyReader<'a> {
470	    /// The fallback: a use of the props object that no safe form below took hands it on.
471	    fn visit_identifier_reference(&mut self, it: &IdentifierReference<'a>) {
472	        if self.whole(it.name.as_str()).is_some() {
473	            self.facts.handed_on = true;
474	        }
475	    }
476	
477	    fn visit_static_member_expression(&mut self, it: &StaticMemberExpression<'a>) {
478	        if self.whole_expr(&it.object).is_some() {
479	            self.read(it.property.name.to_string());
480	            return;
481	        }
482	        walk::walk_static_member_expression(self, it);
483	    }
484	
485	    fn visit_computed_member_expression(&mut self, it: &ComputedMemberExpression<'a>) {
486	        if self.whole_expr(&it.object).is_some()
487	            && let Expression::StringLiteral(key) = &it.expression
488	        {
489	            self.read(js_text::lossy(key.value).into_owned());
490	            return;
491	        }
492	        walk::walk_computed_member_expression(self, it);
493	    }
494	
495	    fn visit_jsx_member_expression(&mut self, it: &JSXMemberExpression<'a>) {
496	        if let JSXMemberExpressionObject::IdentifierReference(object) = &it.object
497	            && self.whole(object.name.as_str()).is_some()
498	        {
499	            self.read(it.property.name.to_string());
500	            return;
501	        }
502	        walk::walk_jsx_member_expression(self, it);
503	    }
504	
505	    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
506	        if let (BindingPattern::ObjectPattern(object), Some(init)) = (&it.id, &it.init)
507	            && self.whole_expr(init).is_some()
508	        {
509	            self.destructure(object);
510	            // Default values and computed keys, not the initializer: it is the props object, taken apart.
511	            self.visit_binding_pattern(&it.id);
512	            return;
513	        }
514	        let nested = matches!(&it.id, BindingPattern::BindingIdentifier(id) if self.is_nested_component(Some(id)))
515	            && it.init.as_ref().is_some_and(|init| {
516	                unwrap(init).is_some() || matches!(peel_expr(init), Expression::ClassExpression(_))
517	            });
518	        self.in_nested(nested, |reader| walk::walk_variable_declarator(reader, it));
519	    }
520	
521	    fn visit_assignment_expression(&mut self, it: &AssignmentExpression<'a>) {
522	        if let AssignmentTarget::ObjectAssignmentTarget(object) = &it.left
523	            && self.whole_expr(&it.right).is_some()
524	        {
525	            for property in &object.properties {
526	                match property {
527	                    AssignmentTargetProperty::AssignmentTargetPropertyIdentifier(property) => {
528	                        self.read(property.binding.name.to_string());
529	                    }
530	                    AssignmentTargetProperty::AssignmentTargetPropertyProperty(property) => {
531	                        match property.name.static_name() {
532	                            Some(key) => self.read(js_text::property_name(&key)),
533	                            None => self.facts.handed_on = true,
534	                        }
535	                    }
536	                }
537	            }
538	            // The rest target is an existing binding the props object is copied into: not followed.
539	            if object.rest.is_some() {
540	                self.facts.handed_on = true;
541	            }
542	            self.visit_assignment_target(&it.left);
543	            return;
544	        }
545	        walk::walk_assignment_expression(self, it);
